//! Full Starved Piranha source, with Surface expanded into the equivalent generic permission.
use ironsmith::{CardDefinition,GameState,ObjectId,PlayerId,Zone};
use ironsmith::decision::{LegalAction,SelectFirstDecisionMaker,compute_legal_actions};
const A:PlayerId=PlayerId(0);const B:PlayerId=PlayerId(1);
const TEXT:&str="Mana cost: {3}{B}\nType: Creature — Fish\nPower/Toughness: 3/2\nMenace\nAs long as you have seven or more cards in your graveyard, you may cast a copy of this card from your graveyard by paying {3}{B}{B} and exiling this card from your graveyard rather than paying its mana cost.";
fn definitions()->[CardDefinition;2]{let(artifact,direct)=ironsmith_compiler::word_claims::with_enforcement_options(true,true,||ironsmith_compiler_runtime::compile_to_artifact("Starved Piranha",TEXT,false)).unwrap();assert!(direct.spell_effect.is_none());assert_eq!(direct.alternative_casts.len(),1);let decoded=ironsmith_compiled_artifact::CompiledCardArtifact::from_json(&artifact.to_json().unwrap()).unwrap();assert_eq!(artifact,decoded);[direct,ironsmith_runtime_catalog::artifact_materializer::materialize_artifact(&decoded).unwrap()]}
fn action(game:&GameState,id:ObjectId)->Option<LegalAction>{compute_legal_actions(game,A).unwrap().into_iter().find(|action|matches!(action,LegalAction::CastSpell{spell_id,from_zone:Zone::Graveyard,..} if *spell_id==id))}
fn announce(game:&mut GameState,action:LegalAction){use ironsmith::game_loop::{PriorityLoopState,PriorityResponse,apply_priority_response_with_dm,apply_decision_context_with_dm};let mut state=PriorityLoopState::new(2);let mut queue=ironsmith::triggers::TriggerQueue::new();let mut dm=SelectFirstDecisionMaker;let mut progress=apply_priority_response_with_dm(game,&mut queue,&mut state,&PriorityResponse::PriorityAction(action),&mut dm).unwrap();for _ in 0..64{if !state.has_pending_action(){return}let ironsmith::GameProgress::NeedsDecisionCtx(ctx)=progress else{panic!("{progress:?}")};progress=apply_decision_context_with_dm(game,&mut queue,&mut state,&ctx,&mut dm).unwrap()}panic!("incomplete cast")}
#[test]
fn full_source_surface_uses_six_other_cards_and_keeps_donor_separate_from_permanent_copy(){
for definition in definitions(){let mut game=GameState::new(vec!["A".into(),"B".into()],20);game.turn.active_player=A;game.turn.priority_player=Some(A);game.turn.phase=ironsmith::game_state::Phase::FirstMain;game.turn.step=None;game.player_mut(A).unwrap().mana_pool.add(ironsmith::mana::ManaSymbol::Black,5);let donor=game.create_object_from_definition(&definition,A,Zone::Graveyard);let original=game.object(donor).unwrap().stable_id;let filler=ironsmith_compiler_runtime::compile_to_runtime_definition("Other graveyard card","Type: Artifact",false).unwrap();for _ in 0..5{game.create_object_from_definition(&filler,A,Zone::Graveyard);}assert!(action(&game,donor).is_none());game.create_object_from_definition(&filler,A,Zone::Graveyard);let selected=action(&game,donor).expect("six other cards enable source permission");game.turn.active_player=B;assert!(action(&game,donor).is_none(),"copy permission preserves creature spell timing");game.turn.active_player=A;announce(&mut game,selected);assert_eq!(game.stack.len(),1);let copy=game.stack[0].object_id;assert_ne!(game.object(copy).unwrap().stable_id,original);let exiled=game.find_object_by_stable_id(original).unwrap();assert_eq!(game.object(exiled).unwrap().zone,Zone::Exile);assert_eq!(game.objects_in_zone(Zone::Graveyard).len(),6,"announced condition remains locked after donor exile lowers seven cards to six");assert_eq!(game.player(A).unwrap().mana_pool.total(),0);assert_eq!(game.cast_origin_snapshot(copy).unwrap().zone,Zone::Graveyard);let copy_stable=game.object(copy).unwrap().stable_id;ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut SelectFirstDecisionMaker).unwrap();let token=game.find_object_by_stable_id(copy_stable).unwrap();assert_eq!(game.object(token).unwrap().zone,Zone::Battlefield);assert_eq!(game.calculated_power(token),Some(3));assert!(game.object_has_ability(token,&ironsmith::static_abilities::StaticAbility::menace()));assert_eq!(game.object(game.find_object_by_stable_id(original).unwrap()).unwrap().zone,Zone::Exile);}}
